+export function paginate<T>(items: T[], page: number, size: number): Page<T> {
+  // Pages are 1-indexed in the new API.
+  const start = (page - 1) * size;
+  const end = start + size;
+  return {
+    items: items.slice(start, end),
+    hasMore: end <= items.length,
+  };
+}

